void _rpc__Send_Command(
			unsigned char locality, _IN_BUFFER request, _OUT_BUFFER* response)
{
    // If TPM is power off, reject any commands.
    if(!s_isPowerOn)
	{
	    response->BufferSize = 0;
	    return;
